hints.code_snippet:
class PaymentProcessor {
  constructor(amount) {
    this.amount = amount;
  }

  processPayment() {
    // This default implementation is redundant, as subclasses will fully override it.
    // A truly 'abstract' method should ideally throw an error here to enforce subclass implementation.
    console.log(`Generic payment initiation for $${this.amount}.`);
    return `Payment initiated generically for $${this.amount}.`;
  }
}

class CreditCardProcessor extends PaymentProcessor {
  constructor(amount, cardNumber) {
    super(amount);
    this.cardNumber = cardNumber;
  }

  processPayment() {
    const lastFour = this.cardNumber.slice(-4);
    return `Processing credit card payment of $${this.amount} for card ending in ${lastFour}.`;
  }
}

class PayPalProcessor extends PaymentProcessor {
  constructor(amount, email) {
    super(amount);
    this.email = email;
  }

  processPayment() {
    return `Processing PayPal payment of $${this.amount} for account ${this.email}.`;
  }
}

// Example usage (will be used for checks):
// const ccPayment = new CreditCardProcessor(100, '1234567890123456');
// console.log(ccPayment.processPayment());
// const ppPayment = new PayPalProcessor(50, 'user@example.com');
// console.log(ppPayment.processPayment());

